html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:.1f}".format(value | float) if value is not none else "" }}{%- endmacro -%}
<style>
.lpl-form { font-family: Cambria, Georgia, serif; font-size: 11.5px; color: #000; line-height: 1.45; }
.lpl-form p { margin: 0 0 8px; }
.lpl-form table { width: 100%; border-collapse: collapse; margin: 0 0 12px; }
.lpl-form tr { page-break-inside: avoid; }
.lpl-form th, .lpl-form td { border: 1px solid #000; padding: 4px 6px; vertical-align: top; text-align: left; }
.lpl-form th { background: #f2f2f2; font-weight: bold; }
.lpl-form h3 { font-size: 12.5px; text-align: center; text-transform: uppercase; margin: 8px 0 12px; }
.lpl-form h4 { font-size: 11.5px; font-weight: bold; margin: 14px 0 6px; }
.lpl-form .scores td, .lpl-form .scores th { text-align: center; }
.lpl-form .scores td { font-weight: bold; }
.lpl-form .narrow { width: 8%; text-align: center; }
.lpl-form .no { width: 4%; }
.lpl-form .muted { color: #444; font-size: 10.5px; }
.lpl-form .pre { white-space: pre-wrap; }
.lpl-form .sign td { height: 30px; }
</style>
{%- set groups = [("Promotion", "Promotion", doc.promotions), ("Salary Increase", "Salary Increase", doc.increases),
                  ("Performance Improvement Plan", "Performance Improvement Plan", doc.improvement_plans),
                  ("Close", "Appraisal Closed, No Change", doc.closed)] -%}
{%- set ns = namespace(undecided=0) -%}
{%- for row in doc.employees if not row.decision %}{% set ns.undecided = ns.undecided + 1 %}{% endfor -%}
<div class="lpl-form">
<h3>Performance Appraisal Report</h3>
<table>
<tr><th style="width:18%">Appraisal Cycle</th><td>{{ v(doc.appraisal_cycle) }}</td>
<th style="width:14%">Plant</th><td>{{ v(doc.branch) }}</td></tr>
<tr><th>Review Date</th><td>{{ day(doc.review_date) }}</td>
<th>Status</th><td>{{ v(doc.status) }}</td></tr>
</table>

<table class="scores">
<tr><th>Appraised</th><th>Average Score</th><th>Below the Pass Mark</th><th>Appraisals Completed</th>
<th>Promotions</th><th>Salary Increases</th><th>Improvement Plans</th><th>Closed</th></tr>
<tr><td>{{ doc.appraised or 0 }}</td><td>{{ num(doc.average_score) }}%</td><td>{{ doc.below_pass or 0 }}</td>
<td>{{ num(doc.completion) }}%</td><td>{{ doc.promotions or 0 }}</td><td>{{ doc.increases or 0 }}</td>
<td>{{ doc.improvement_plans or 0 }}</td><td>{{ doc.closed or 0 }}</td></tr>
</table>

{%- for group in groups %}
{%- set decision = group[0] %}
{%- if group[2] %}
<h4>{{ group[1] }} ({{ group[2] }})</h4>
<table>
<tr><th class="no">#</th><th>Employee</th><th style="width:19%">Job Title</th><th style="width:17%">Department</th>
<th class="narrow">Score</th><th style="width:11%">Rating</th>
{%- if decision == "Salary Increase" %}<th class="narrow">Increase</th>{% endif %}
<th style="width:21%">Remarks</th></tr>
{%- for row in doc.employees if row.decision == decision %}
<tr><td class="no">{{ loop.index }}</td>
<td>{{ v(row.employee_name or row.employee) }}
{%- if row.proposed_decision and row.proposed_decision != row.decision %}
<div class="muted">HR proposed: {{ v(row.proposed_decision) }}</div>
{%- endif %}</td>
<td>{{ v(row.designation) }}</td><td>{{ v(row.department) }}</td>
<td class="narrow">{{ num(row.total_score) }}</td><td>{{ v(row.band) }}</td>
{%- if decision == "Salary Increase" %}<td class="narrow">{% if row.increase_percent %}{{ num(row.increase_percent) }}%{% endif %}</td>{% endif %}
<td class="pre">{{ v(row.remarks) }}</td></tr>
{%- endfor %}
</table>
{%- endif %}
{%- endfor %}

{%- if ns.undecided %}
<h4>Not Decided Yet ({{ ns.undecided }})</h4>
<table>
<tr><th class="no">#</th><th>Employee</th><th style="width:19%">Job Title</th><th style="width:17%">Department</th>
<th class="narrow">Score</th><th style="width:11%">Rating</th><th style="width:21%">Remarks</th></tr>
{%- for row in doc.employees if not row.decision %}
<tr><td class="no">{{ loop.index }}</td><td>{{ v(row.employee_name or row.employee) }}</td>
<td>{{ v(row.designation) }}</td><td>{{ v(row.department) }}</td>
<td class="narrow">{{ num(row.total_score) }}</td><td>{{ v(row.band) }}</td><td class="pre">{{ v(row.remarks) }}</td></tr>
{%- endfor %}
</table>
{%- endif %}

<h4>Approval</h4>
<table class="sign">
<tr><th style="width:24%"></th><th>Name</th><th style="width:16%">Date</th><th style="width:24%">Signature</th></tr>
<tr><th>Prepared by (HR)</th><td>{{ who(doc.sent_by) }}</td><td>{{ day(doc.shared_on) }}</td><td></td></tr>
<tr><th>General Manager</th><td>{{ who(doc.gm_by) }}</td><td>{{ day(doc.gm_on) }}</td><td></td></tr>
<tr><th>Executive Director</th><td>{{ who(doc.decided_by) }}</td><td>{{ day(doc.decided_on) }}</td><td></td></tr>
</table>
{%- if doc.gm_remarks %}
<p class="pre"><b>General Manager's remarks:</b> {{ v(doc.gm_remarks) }}</p>
{%- endif %}
{%- if doc.management_remarks %}
<p class="pre"><b>Executive Director's remarks:</b> {{ v(doc.management_remarks) }}</p>
{%- endif %}
</div>
